<?php
declare(strict_types=1);
define('CMS_ROOT',sys_get_temp_dir().'/cms-seo-render-'.bin2hex(random_bytes(4)));mkdir(CMS_ROOT,0700,true);require dirname(__DIR__).'/system/core/Bootstrap/autoload.php';
use Cms\Core\Config\Settings;use Cms\Core\Content\{ContentRepository,ContentTypeRegistry,ContentFrontController};use Cms\Core\Migration\MigrationRunner;use Cms\Core\Logging\FileLogger;
function cpdir(string$a,string$b):void{mkdir($b,0700,true);foreach(scandir($a)as$f){if($f==='.'||$f==='..')continue;is_dir($a.'/'.$f)?cpdir($a.'/'.$f,$b.'/'.$f):copy($a.'/'.$f,$b.'/'.$f);}}
foreach(['default','daiying_media','safe']as$t)cpdir(dirname(__DIR__).'/content/themes/'.$t,CMS_ROOT.'/content/themes/'.$t);
