$r->patch($id,['meta'=>['seo_keywords'=>'']]);$html=$controller->article(new \Cms\Core\Http\Request('GET','/articles/seo-article'))->body();if(!str_contains($html,'name="keywords" content="global keywords"'))throw new RuntimeException($t.' global fallback missing');echo "[PASS] $t global fallback\n";$r->patch($id,['meta'=>['seo_keywords'=>'article, unique']]);}
